SourceCode.Declaration:
/// <summary>
/// Extension of form ProdTableCreate
/// </summary>
[ExtensionOf(formStr(ProdTableCreate))]
final class AVAProdTableCreateFrm_Extension
{
}

Method.Source:
/// <summary>
/// sets the field AVABatchProjId in ProdTable if correct record is attached from caller
/// </summary>
public void avaSetBatchProjId()
{
    if(this.avaIsCalledFromProjForm()
        && this.args().parm())
    {
        ProjId locProjId        = this.args().parm();
        ProjTable locProjTable  = ProjTable::find(locProjId);

        prodTable.AVABatchProjId = locProjTable.ProjId;
    }
}

/// <summary>
/// checks if the item is valid for a project production
/// </summary>
/// <returns>boolean</returns>
public boolean avaValidateItemId()
{
    if(prodTable.AVABatchProjId
        && !prodTable.inventTable().projCategoryId)
    {
        return checkFailed(strFmt("@NDX:NXABatchProjItemNoCategory", prodTable.ItemId));
    }

    return true;
}

/// <summary>
/// Extension of canClose method
/// </summary>
/// <returns>boolean</returns>
boolean canClose()
{
    boolean ret;

    ret = next canClose();

    ret = ret & this.avaProjectCheckLineProperty();

    return ret;
}

 /// <summary>
 /// if prodTable has a BatchProjId it checks if the project has a LinePropertyId associated
 /// </summary>
 /// <returns>boolean</returns>
 public boolean avaProjectCheckLineProperty()
 {
     if(this.closedOk()
         && prodTable.AVABatchProjId
         && prodTable.avaBatchProjTable().avaGetProjLinePropertyId() == '')
     {
         return checkFailed(strFmt("@NDX:NXABatchProjNoPropertyLine", prodTable.AVABatchProjId));
     }
     else
     {
         return true;
     }
}

/// <summary>
/// checks if menu item is called from form ProjProjectsListPage of form ProjTable
/// </summary>
/// <returns>boolean</returns>
public boolean avaIsCalledFromProjForm()
{
    Object      myCaller;
    FormRun     callerForm;
    boolean     calledFromListPage = false;

    if (this.args())
    {
        myCaller = this.args().caller();

        if (myCaller && myCaller is FormRun)
        {
            callerForm = myCaller;
            if ((callerForm.name() == formStr(ProjProjectsListPage)
                    || callerForm.name() == formStr(ProjTable))
                && this.args().menuItemName() == menuitemDisplayStr(PmfBatchOrderNew))
            {
                calledFromListPage = true;
            }
        }
    }
    return calledFromListPage;
}
